1	import { BadRequestException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	export interface ItemExpandido {
5	  product_id: number;
6	  quantity: number;
7	  unit_price: number;
8	  combo_nome?: string;
9	  combo_quantidade?: number;
10	}
11	
12	@Injectable()
13	export class CombosService {
14	  constructor(private supabase: SupabaseService) {}
15	
16	  // Combo só fica disponível pra venda se ele mesmo estiver ativo E todos os produtos
17	  // que o compõem tiverem estoque > 0 — se faltar 1 ingrediente, o combo some da
18	  // venda igual um produto avulso zerado (mesma regra de deliveryhub_estoque_zero_bloqueia_venda).
19	  // Não filtra a linha fora — devolve `disponivel` pro chamador decidir (endpoint de
20	  // venda exclui, tela de gestão do dono mostra tudo com um aviso).
21	  async listarComDisponibilidade(restaurantId: number) {
22	    const { data, error } = await this.supabase.client
23	      .from('combos')
24	      .select(
25	        'id, name, description, price, preco_promo, image_url, is_active, destaque, created_at, combo_items(quantity, products(quantidade_estoque, is_active))',
26	      )
27	      .eq('restaurant_id', restaurantId)
28	      .order('destaque', { ascending: false })
29	      .order('name');
30	    if (error) throw error;
31	
32	    return (data ?? []).map((c: any) => {
33	      const { combo_items, ...resto } = c;
34	      const itens = combo_items ?? [];
35	      const disponivel =
36	        c.is_active &&
37	        itens.length > 0 &&
38	        itens.every((ci: any) => ci.products?.is_active && (ci.products?.quantidade_estoque ?? 0) > 0);
39	      return { ...resto, disponivel };
40	    });
41	  }
42	
43	  // Combo não é uma entidade vendável própria no pedido — vira várias linhas dos
44	  // produtos reais que o compõem (order_items continua só sabendo de products,
45	  // então estoque/KDS/impressão por setor funcionam sem mudar nada). O preço de
46	  // cada linha é o `preco_no_combo` que o dono escolheu pra aquele produto
47	  // especificamente (definido no cadastro do combo, não é mais um fator único).
48	  async expandir(comboId: number, quantidadeComprada: number, restaurantId: number): Promise<ItemExpandido[]> {
49	    if (quantidadeComprada < 1) throw new BadRequestException('Quantidade do combo inválida');
50	
51	    const { data: combo } = await this.supabase.client
52	      .from('combos')
53	      .select(
54	        'id, name, restaurant_id, is_active, combo_items(product_id, quantity, preco_no_combo, products(price, is_active, quantidade_estoque))',
55	      )
56	      .eq('id', comboId)
57	      .maybeSingle();
58	
59	    if (!combo || combo.restaurant_id !== restaurantId) throw new NotFoundException(`Combo ${comboId} não encontrado`);
60	    if (!combo.is_active) throw new BadRequestException(`Combo ${comboId} não está disponível`);
61	
62	    const itens = ((combo as any).combo_items ?? []) as Array<{
63	      product_id: number;
64	      quantity: number;
65	      preco_no_combo: number | null;
